import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Uninstall and rollback","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/uninstall.md","filePath":"guide/uninstall.md"}'),s={name:"docs/guide/uninstall.md"};function l(r,e,o,h,p,d){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="uninstall-and-rollback" tabindex="-1">Uninstall and rollback <a class="header-anchor" href="#uninstall-and-rollback" aria-label="Permalink to &quot;Uninstall and rollback&quot;">​</a></h1><p>Removal has two parts: restore the running OS windows that Kittyscape still owns, then remove its user-local configuration entry and installed files. A file removal alone cannot restore an already-running window.</p><div class="warning custom-block"><p class="custom-block-title">Restore before removing files</p><p>The setup helper cannot unload a watcher from an already-running kitty process. Restore and pause those instances first. No public package is available yet; these instructions apply to the local development bundle.</p></div><h2 id="restore-first" tabindex="-1">Restore first <a class="header-anchor" href="#restore-first" aria-label="Permalink to &quot;Restore first&quot;">​</a></h2><p>Use <strong>Ctrl+Shift+F10</strong>, the <a href="./../reference/actions.html">restore action</a>, while the watcher is loaded. This restores owned baselines and pauses the whole instance, including windows opened later. Check the original image in each affected OS window, including the no-image case. Restoration must skip windows whose background was replaced by another tool.</p><p>If ownership or baseline capture is uncertain, preserve the current working terminal and inspect <a href="./kitty-settings.html">restoration guidance</a>. Do not clear every window’s background.</p><h2 id="remove-owned-setup" tabindex="-1">Remove owned setup <a class="header-anchor" href="#remove-owned-setup" aria-label="Permalink to &quot;Remove owned setup&quot;">​</a></h2><p>From the extracted bundle, preview removal, then apply it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kitty-config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/kitty</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kitty-config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/kitty</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>Use the same kitty configuration directory chosen during installation. You can also run the installed helper, for example <code>kitty +launch &#39;/tmp/kittyscape trial/kittyscape/0.2.0.dev0/setup.py&#39; uninstall --kitty-config-dir ~/.config/kitty --apply</code> as one command.</p><p>Review the preview’s owned-file list. Uninstall removes the exact marked include block while preserving later unrelated edits. It removes only unchanged owned files. Modified or untracked files are retained and reported; the backup and receipt remain when retained content still needs review.</p><p>The helper preserves <code>kittyscape.json</code>, user images, shell startup files, included configurations, and existing symlink relationships. Repeated removal handles the already-removed state without duplicating changes.</p><p>Open a fresh isolated kitty instance and confirm that its ordinary background and rendering preferences remain intact. Keep the backup until both running-window and fresh-window checks pass.</p><h2 id="roll-back-an-installation" tabindex="-1">Roll back an installation <a class="header-anchor" href="#roll-back-an-installation" aria-label="Permalink to &quot;Roll back an installation&quot;">​</a></h2><p>Rollback is the appropriate operation when you want to undo an installation and the installed configuration has not received later edits:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kitty-config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/kitty</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kitty-config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/kitty</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>Rollback requires the original backup to be readable and match its recorded hash. The installed <code>kitty.conf</code> must also remain unchanged. Otherwise rollback refuses to overwrite user work. Use uninstall to preserve later unrelated edits, or reconcile the conflict manually after reading the retained files.</p><p>The acceptance check compares file bytes, permissions, symlink targets, and unrelated content with the pre-install snapshot. See the <a href="./../development/compatibility-findings.html">runtime and packaging evidence</a>.</p><h2 id="manual-removal" tabindex="-1">Manual removal <a class="header-anchor" href="#manual-removal" aria-label="Permalink to &quot;Manual removal&quot;">​</a></h2><p>For a <a href="./installation.html#manual-installation">manual installation</a>, restore/pause the running instance first. Remove the exact include line you added, then remove only the include file and versioned bundle recorded in your inventory. Preserve edited files, rules, images, and unrelated content for review.</p><p>Do not use helper uninstall for a manual installation without an ownership receipt. Open a fresh isolated kitty instance and verify its normal background. Keep your backup until both running and fresh instances pass.</p>`,21)])])}const u=a(s,[["render",l]]);export{k as __pageData,u as default};
